8_mc = [];
Th230_U238_mc = [];
Th232_U238_mc = [];
[m,~] = size(IsoRatiosAgeEqn_data);
for i = 1:m
 U234_U238_mc(i,:) = U234_U238(i) + U234_U238_1s(i).*randn(1,n);
 Th230_U238_mc(i,:) = Th230_U238(i) + Th230_U238_1s(i).*randn(1,n);
 Th232_U238_mc(i,:) = Th232_U238(i) + Th232_U238_1s(i).*randn(1,n);
end

Age_uncorr = [];
Age_corr = [];
U234_U238_init = [];
for i = 1:m
 for j = 1:n
 Age_uncorr(i,j) = fzero(@(t) ...
 Th230_U238_mc(i,j)-(1-exp(-Lam230*t))-...
 Lam230/(Lam230-Lam234)*(exp(-Lam234*t)-exp(-Lam230*t))*exp(Lam234*t)*
 (U234_U238_mc(i,j)-1),Agestart);
 Age_corr(i,j) = fzero(@(t) ...
 Th230_U238_mc(i,j)-(1-exp(-Lam230*t))-...
 exp(-Lam230*t)*Th230_Th232_init_mc(j)*Th232_U238_mc(i,j)-...
 Lam230/(Lam230-Lam234)*(exp(-Lam234*t)-exp(-Lam230*t))*exp(Lam234*t)*
 (U234_U238_mc(i,j)-1),Agestart);
 U234_U238_init(i,j) = U234_U238_mc(i,j)*exp(Lam234*Age_corr(i,j));
 end
end
